public NVAPIResponseContract getEmployeeDetailsByEmail(str email)
{
    int errorCode = #SuccessCode;
    List errorsList = new List(Types::String);
    List workerList = new List(Types::Class);
    if(email == "")
    {
        errorsList.addEnd("Email must specified.");
        errorCode = #BadRequest;
    }
    else
    {
        workerList = NVHcmGetWorkerDetails::construct("", email).getWorkers();
        if(workerList.empty())
        {
            errorsList.addEnd(strFmt("No record(s) found against email '%1'.", email));
            errorCode = #NotFound;
        }
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(workerList);

    return responseContract;
}

public NVAPIResponseContract getManagerTeam(str managerWorker, str nameFilter = "", int pageNumber = 0, int recordCountPerPage = 0)
{
    int errorCode = #SuccessCode;
    List errorsList = new List(Types::String);
    List workerList = new List(Types::Class);
    if(managerWorker == "")
    {
        errorsList.addEnd("Manager worker Id must specified.");
        errorCode = #BadRequest;
    }
    else if(HcmWorker::findByPersonnelNumber(managerWorker).RecId == 0)
    {
        errorsList.addEnd(strFmt("No record(s) found against worker Id '%1'.", managerWorker));
        errorCode = #BadRequest;
    }
    else
    {
        workerList = NVHcmGetWorkerDetails::construct("", "", pageNumber, recordCountPerPage, managerWorker).getWorkerTeam(nameFilter);
        /*if(workerList.empty())
        {
            errorsList.addEnd(strFmt("No record(s) found against manager worker Id '%1'.", managerWorker));
            errorCode = #NotFound;
        }*/
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(workerList);

    return responseContract;
}

public NVAPIResponseContract getLeaveTypes(str workerId)
{
    int errorCode = #SuccessCode;
    List errorsList = new List(Types::String);
    List leaveTypeList = new List(Types::Class);

    HcmWorker worker = HcmWorker::findByPersonnelNumber(workerId);
    if(workerId == "")
    {
        errorsList.addEnd("Worker Id must specified.");
        errorCode = #BadRequest;
    }
    else if(worker.RecId == 0)
    {
        errorsList.addEnd(strFmt("Worker not found against worker Id  '%1'.", workerId));
        errorCode = #NotFound;
    }
    else
    {
        Query query = new Query(queryStr(LeaveTypeLookupForWorker));
        query.allowCrossCompany(true);
        QueryBuildDataSource enrollmentLeaveDS = query.dataSourceTable(tableNum(LeaveEnrollmentByTypeView));
        enrollmentLeaveDS.addRange(fieldNum(LeaveEnrollmentByTypeView, Worker)).value(SysQuery::value(worker.RecId));
        enrollmentLeaveDS.addRange(fieldNum(LeaveEnrollmentByTypeView, RequestType)).value(SysQuery::value(LeaveTypeRequestType::TimeOff));
        QueryRun queryRun = new QueryRun(query);
        while(queryRun.next())
        {
            LeaveEnrollmentByTypeView leaveEnrollmentByTypeView = queryRun.get(tableNum(LeaveEnrollmentByTypeView));
            LeaveType leaveType = LeaveType::findCrossCompany(leaveEnrollmentByTypeView.Type);
            NVHcmWorkerLeaveTypeContract leaveTypeContract = new NVHcmWorkerLeaveTypeContract();

            leaveTypeContract.parmLeaveTypeId(leaveType.Type);
            leaveTypeContract.parmDescription(leaveType.Description);
            leaveTypeContract.parmCompany(leaveType.DataAreaId);
            leaveTypeContract.parmIsAttachmentRequired(leaveType.IsAttachmentRequired);
            leaveTypeContract.parmHideLeaveBalances(leaveType.HideLeaveBalances);

            NVLeavePlanTypeBalanceView leavePlanTypeBalanceView;
            select crosscompany sum(Balance), sum(Used), sum(TotalBalance) from leavePlanTypeBalanceView
                where leavePlanTypeBalanceView.Worker       == worker.RecId
                    && leavePlanTypeBalanceView.DataAreaId  == leaveType.DataAreaId
                    && leavePlanTypeBalanceView.LeaveType   == leaveType.RecId;
            leaveTypeContract.parmLeaveUsedDays(leavePlanTypeBalanceView.Used);
            leaveTypeContract.parmLeaveRemainingBalance(leavePlanTypeBalanceView.Balance);
            leaveTypeContract.parmLeaveBalance(leavePlanTypeBalanceView.TotalBalance);
            leaveTypeContract.parmBalanceRenewalDate(mkDate(1, 1, 2026));

            leaveTypeList.addEnd(leaveTypeContract);
        }

        if(leaveTypeList.empty())
        {
            errorsList.addEnd(strFmt("No leave type(s) assigned against worker Id  '%1'.", workerId));
            errorCode = #NotFound;
        }
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(leaveTypeList);

    return responseContract;
}

public NVAPIResponseContract getNextWorkingDay(str workerId, date leaveEndingDate)
{
    int errorCode = #SuccessCode;
    List errorsList = new List(Types::String);
    List nextWorkingDate = new List(Types::Date);
    date nextDate = leaveEndingDate;

    HcmWorker worker = HcmWorker::findByPersonnelNumber(workerId);

    if(leaveEndingDate == dateNull())
    {
        errorsList.addEnd("Leave ending date must be specified.");
        errorCode = #BadRequest;
    }

    if(workerId == "")
    {
        errorsList.addEnd("Worker Id must specified.");
        errorCode = #BadRequest;
    }
    else if(worker.RecId == 0)
    {
        errorsList.addEnd(strFmt("Worker not found against worker Id  '%1'.", workerId));
        errorCode = #NotFound;
    }
    else
    {
        nextDate = worker.findNextWorkingDate(nextDate);
        nextWorkingDate.addEnd(nextDate);
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(nextWorkingDate);

    return responseContract;
}

public NVAPIResponseContract pushLeaveRequest(NVWorkerLeaveRequestContract request)
{
    int errorCode   = #SuccessCode;
    List errorsList = new List(Types::String);
    List retList    = new List(Types::String);

    HcmWorker worker = HcmWorker::findByPersonnelNumber(request.parmWorkerId());

    if(request.parmWorkerId() == "")
    {
        errorsList.addEnd("Worker Id must specified.");
        errorCode = #BadRequest;
    }
    else if(worker.RecId == 0)
    {
        errorsList.addEnd(strFmt("Worker not found against worker Id  '%1'.", request.parmWorkerId()));
        errorCode = #NotFound;
    }

    LeaveType leaveType = LeaveType::findByTypeCrossCompany(request.parmLeaveTypeId());        
    if(request.parmLeaveTypeId() == "")
    {
        errorsList.addEnd("Leave type Id must specified.");
        errorCode = #BadRequest;
    }
    else if(leaveType.RecId == 0)
    {
        errorsList.addEnd(strFmt("Leave not found against leave type '%1'.", request.parmLeaveTypeId()));
        errorCode = #NotFound;
    }

    if(request.parmStartDate() > request.parmEndDate())
    {
        errorsList.addEnd(strFmt("Leave start date must be before or equal to end date."));
        errorCode = #BadRequest;
    }

    if(request.parmEndDate() > request.parmWorkResumeDate())
    {
        errorsList.addEnd(strFmt("Leave end date must be before work resume date."));
        errorCode = #BadRequest;
    }

    HcmEmployment   employment;
    if(errorCode == #SuccessCode)
    {
        utcdatetime requestDateTime = DateTimeUtil::newDateTime(request.parmStartDate(), 0);

        LeaveEnrollment enrollment;
        select employment
            order by employment.ModifiedDateTime desc
            where employment.Worker         == worker.RecId
                && employment.ValidFrom     <= requestDateTime
                && employment.ValidTo       >= requestDateTime;

        while (employment.RecId != 0 && enrollment.RecId == 0)
        {
            changecompany(CompanyInfo::findRecId(employment.LegalEntity).DataArea)
            {
                enrollment = LeaveEnrollment::findByWorkerType(worker.RecId, leaveType.RecId);
            }

            if(!enrollment)
            {
                next employment;
            }
        }

        if(employment.RecId == 0 || enrollment.RecId == 0)
        {
            errorsList.addEnd(strFmt("No employment or leave setup found for worker '%1'.", request.parmWorkerId()));
            errorCode = #NotFound;
        }
    }

    if(errorCode == #SuccessCode)
    {            
        changecompany(CompanyInfo::findRecId(employment.LegalEntity).DataArea)
        {
            ttsbegin;
            LeaveRequest leaveRequest;
            leaveRequest.RequestDate                    = request.parmStartDate();
            leaveRequest.Worker                         = worker.RecId;
            leaveRequest.SubmittedByUser                = curUserId();
            leaveRequest.LeaveClassification            = LeaveClassification::TimeOff;
            leaveRequest.NVLeaveAppliedDate             = request.parmApplicationDate();
            leaveRequest.NVWorkResumeDate               = request.parmWorkResumeDate();
            leaveRequest.Comment                        = request.parmComment();
            leaveRequest.IsSubmittedByHumanResources    = UnknownNoYes::No;
            leaveRequest.Status                         = LeaveRequestApprovalStatus::Completed;
            leaveRequest.insert();

            if(leaveRequest)
            {
                NVTimesheetChangeHandler::insertNewRef(leaveRequest.Worker, leaveRequest.TableId, leaveRequest.RecId);
            }

            LeavePlanRecId leanPlan = NVLeavePlanEventHandler::getPlanForLeaveType(leaveType.RecId, worker.RecId).RecId;
            date leaveDate = request.parmStartDate();
            while(leaveDate <= request.parmEndDate())
            {
                LeaveRequestDetail leaveRequestDetail;
                leaveRequestDetail.Request      = leaveRequest.recid;
                leaveRequestDetail.Amount       = 1;
                leaveRequestDetail.LeaveDate    = leaveDate;
                leaveRequestDetail.LeaveType    = leaveType.RecId;
                leaveRequestDetail.insert();

                LeaveBankTransaction leaveBankTransaction;
                leaveBankTransaction.clear();
                leaveBankTransaction.Worker             = worker.RecId;
                leaveBankTransaction.LeavePlan          = leanPlan;
                leaveBankTransaction.LeaveType          = leaveType.RecId;
                leaveBankTransaction.TransactionDate    = leaveDate;
                leaveBankTransaction.TransactionType    = LeaveTransactionType::Request;
                leaveBankTransaction.Amount             = -1;
                leaveBankTransaction.Comment            = leaveRequest.Comment;

                leaveBankTransaction.insert();

                leaveDate++;
            }

            if(request.parmAttachment() != null)
            {
                DocuType docuType = DocuType::findGroup(DocuTypeGroup::File);
                ListIterator attachmentListIter = new ListIterator(request.parmAttachment());
                int counter = 1;
                while(attachmentListIter.more())
                {
                    NVWorkerLeaveRequestAttachmentContract attachment = attachmentListIter.value();
                    Filename fileName = strFmt("%1-%2.%3", leaveRequest.RequestId, counter, attachment.parmExtension());

                    DocuRef docuRef;
                    docuRef.initValue();
                    docuRef.RefTableId      = leaveRequest.TableId;
                    docuRef.RefRecId        = leaveRequest.RecId;
                    docuRef.RefCompanyId    = leaveRequest.DataAreaId;
                    docuRef.Name            = fileName;
                    docuRef.TypeId          = docuType.TypeId;
                    docuRef.insert();

                    DocuAction docuAction = DocuAction::newDocuRef(docuRef);
                    if (docuAction is DocuActionFile)
                    {
                        System.IO.MemoryStream memoryStream = new System.IO.MemoryStream(System.Convert::FromBase64String(attachment.parmFile()));

                        if (memoryStream != null)
                        {
                            using (System.IO.MemoryStream fileStream = memoryStream)
                            {
                                DocuAction action = docuRef.docuAction();
                                action.attachFile(docuRef, fileName, '', fileStream);
                            }
                        }
                    }
                    counter++;

                    attachmentListIter.next();
                }
            }

            ttscommit;
        }
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(retList);

    return responseContract;

}

public NVAPIResponseContract getWorkerPayPeriod(str workerId)
{
    int errorCode = #SuccessCode;
    List errorsList = new List(Types::String);
    List payPeriodList = new List(Types::Class);

    HcmWorker worker = HcmWorker::findByPersonnelNumber(workerId);
    if(workerId == "")
    {
        errorsList.addEnd("Worker Id must specified.");
        errorCode = #BadRequest;
    }
    else if(worker.RecId == 0)
    {
        errorsList.addEnd(strFmt("Worker not found against worker Id  '%1'.", workerId));
        errorCode = #NotFound;
    }
    else
    {
        Query query = new Query();
        query.allowCrossCompany(true);
        QueryBuildDataSource workerDS = query.addDataSource(tableNum(HcmWorker));

        if(workerId != "")
        workerDS.addRange(fieldNum(HcmWorker, PersonnelNumber)).value(workerId);

        QueryRun queryRun = new QueryRun(query);

        while(queryRun.next())
        {
            NVHcmWorkerPayPeriodContract payPeriodContract = new NVHcmWorkerPayPeriodContract();

            payPeriodContract.parmWorkerId(worker.PersonnelNumber);
            payPeriodContract.parmCompany(curExt());
            payPeriodContract.parmPayPeriod('June 2025');
            payPeriodContract.parmPeriodStartDate(mkDate(1,6,2025));
            payPeriodContract.parmPeriodStartDate(mkDate(30,6,2025));

            payPeriodList.addEnd(payPeriodContract);
        }
    }
    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(payPeriodList);

    return responseContract;
}

public NVAPIResponseContract getWorkerSalaryDetails(str workerId, date periodStartDate, date periodEndDate)
{
    int errorCode = #SuccessCode;
    List errorsList = new List(Types::String);
    List salaryDetailsList = new List(Types::Class);

    if(periodStartDate == dateNull())
    {
        errorsList.addEnd("Period start date must specified.");
        errorCode = #BadRequest;
    }

    if(periodEndDate == dateNull())
    {
        errorsList.addEnd("Period end date must specified.");
        errorCode = #BadRequest;
    }

    HcmWorker worker = HcmWorker::findByPersonnelNumber(workerId);
    if(workerId == "")
    {
        errorsList.addEnd("Worker Id must specified.");
        errorCode = #BadRequest;
    }
    else if(worker.RecId == 0)
    {
        errorsList.addEnd(strFmt("Worker not found against worker Id  '%1'.", workerId));
        errorCode = #NotFound;
    }

    if(errorCode == #SuccessCode)
    {
        Query query = new Query();
        query.allowCrossCompany(true);
        QueryBuildDataSource workerDS = query.addDataSource(tableNum(HcmWorker));

        workerDS.addRange(fieldNum(HcmWorker, PersonnelNumber)).value(workerId);

        QueryRun queryRun = new QueryRun(query);

        while(queryRun.next())
        {
            NVHcmWorkerSalaryDetailsContract salaryDetails = new NVHcmWorkerSalaryDetailsContract();

            salaryDetails.parmWorkerId(worker.PersonnelNumber);
            salaryDetails.parmWorkerName(worker.name());
            salaryDetails.parmCompany(curExt());

            salaryDetailsList.addEnd(salaryDetails);
        }
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(salaryDetailsList);

    return responseContract;
}

