public NVAPIResponseContract getTrvLocationsPerDiem(str fromLocation)
{
    int errorCode = #SuccessCode;
    List errorsList = new List(Types::String);
    List trvLocationList = new List(Types::Class);

    if(fromLocation == "")
    {
        errorsList.addEnd("From location must specified.");
        errorCode = #BadRequest;
    }
    else if(NVTrvWorkerLocation::find(fromLocation).RecId == 0)
    {
        errorsList.addEnd(strFmt("From location not found against Id  '%1'.", fromLocation));
        errorCode = #NotFound;
    }

    if(errorCode == #SuccessCode)
    {
        Query query = new Query();
        QueryBuildDataSource trvWorkerLocationDS = query.addDataSource(tableNum(NVTrvWorkerLocationPerDiem));

        trvWorkerLocationDS.addRange(fieldNum(NVTrvWorkerLocationPerDiem, FromLocation)).value(fromLocation);

        QueryRun queryRun = new QueryRun(query);

        while(queryRun.next())
        {
            NVTrvWorkerLocationPerDiem  locationPerDiem = queryRun.get(tableNum(NVTrvWorkerLocationPerDiem));
            NVTrvWorkerLocation         fromTrvLocation = NVTrvWorkerLocation::find(locationPerDiem.FromLocation);
            NVTrvWorkerLocation         toTrvLocation   = NVTrvWorkerLocation::find(locationPerDiem.ToLocation);

            NVTrvWorkerLocationPerDiemContract contract = new NVTrvWorkerLocationPerDiemContract();

            contract.parmFromLocationId(locationPerDiem.FromLocation);
            contract.parmFromLocationDescription(fromTrvLocation.Description);
            contract.parmToLocationId(locationPerDiem.ToLocation);
            contract.parmToLocationDescription(toTrvLocation.Description);
            contract.parmCurrency(locationPerDiem.CurrencyCode);
            contract.parmPurpose(enum2Str(locationPerDiem.DefaultPurpose));
            contract.parmPerDiem(locationPerDiem.PerDiem);
            contract.parmHotelPercentage(locationPerDiem.HotelPercent);
            contract.parOtherAllowancePercentage(locationPerDiem.OtherAllowancePercent);

            trvLocationList.addEnd(contract);
        }
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(trvLocationList);

    return responseContract;
}

[AifCollectionTypeAttribute('request', Types::Class, classStr(NVTrvWorkerCalcRequestContract))]
public NVAPIResponseContract getTravelCalculationDetails(List request)
{
    int                         errorCode   = #SuccessCode;
    List                        errorsList  = new List(Types::String);
    List                        retList     = new List(Types::Class);
    ListIterator                requestIter = new ListIterator(request);

    while(requestIter.more())
    {
        NVTrvWorkerCalcRequestContract requestContract = requestIter.value();
        if(requestContract.parmESSRequest() == "")
        {
            NVTrvWorkerLocation fromLocation = NVTrvWorkerLocation::find(requestContract.parmFromLocation());
            if(requestContract.parmFromLocation() == "")
            {
                errorsList.addEnd("From location must specified.");
                errorCode = #BadRequest;
            }
            else if(fromLocation.RecId == 0)
            {
                errorsList.addEnd(strFmt("From location not found against Id  '%1'.", requestContract.parmFromLocation()));
                errorCode = #NotFound;
            }

            NVTrvWorkerLocation toLocation = NVTrvWorkerLocation::find(requestContract.parmToLocation());
            if(requestContract.parmToLocation() == "")
            {
                errorsList.addEnd("To location must specified.");
                errorCode = #BadRequest;
            }
            else if(toLocation.RecId == 0)
            {
                errorsList.addEnd(strFmt("To location not found against Id  '%1'.", requestContract.parmToLocation()));
                errorCode = #NotFound;
            }

            if(requestContract.parmFromDate() > requestContract.parmToDate())
            {
                errorsList.addEnd(strFmt("From date must be before or equal to To date."));
                errorCode = #BadRequest;
            }
        }

        requestIter.next();
    }

    if(errorCode == #SuccessCode)
    {
        requestIter = new ListIterator(request);
        while(requestIter.more())
        {
            NVTrvWorkerCalcRequestContract  requestContract = requestIter.value();
            NVTrvWorkerExpenseRequest       travelRequest   = NVTrvWorkerExpenseRequest::findESSRequest(requestContract.parmESSRequest());

            if(travelRequest.RecId == 0)
            {
                travelRequest.setTmp();

                travelRequest.FromLocation          = requestContract.parmFromLocation();
                travelRequest.ToLocation            = requestContract.parmToLocation();
                travelRequest.FromDate              = requestContract.parmFromDate();
                travelRequest.ToDate                = requestContract.parmToDate();
                travelRequest.IncludeLastDayHotel   = requestContract.parmIncludeLastDayHotel();
                travelRequest.RequestCreatedDate    = DateTimeUtil::getSystemDate(DateTimeUtil::getCompanyTimeZone());

                travelRequest.modifiedField(fieldNum(NVTrvWorkerExpenseRequest, ToLocation));
                travelRequest.doInsert();
            }

            NVTrvWorkerCalcResponseContract responseContract = new NVTrvWorkerCalcResponseContract();

            responseContract.parmESSRequest(requestContract.parmESSRequest());
            responseContract.parmTotalDays(travelRequest.totalDays());
            responseContract.parmPerDiem(travelRequest.PerDiem);
            responseContract.parmCurrency(travelRequest.CurrencyCode);
            responseContract.parmHotelAllowancePerc(travelRequest.HotelPercent);
            responseContract.parmHotelAllowanceAmount(travelRequest.hotelAllowance() * responseContract.parmTotalDays());
            responseContract.parmOtherAllowancePerc(travelRequest.OtherAllowancePercent);
            responseContract.parmOtherAllowanceAmount(travelRequest.otherAllowance() * responseContract.parmTotalDays());
            responseContract.parmTotalValue(travelRequest.TotalValue);
            responseContract.parmExchangeRate(travelRequest.exchangeRateMST());
            responseContract.parmTotalValueReportingCurrency(travelRequest.amountMST());
            responseContract.parmReportingCurrency(Ledger::reportingCurrency());

            retList.addEnd(responseContract);
            requestIter.next();
        }
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(retList);

    return responseContract;

}

public NVAPIResponseContract pushWorkerTravelRequest(NVTrvWorkerRequestContract request)
{
    int     errorCode   = #SuccessCode;
    List    errorsList  = new List(Types::String);
    List    retList     = new List(Types::String);

    HcmWorker worker = HcmWorker::findByPersonnelNumber(request.parmWorkerId());
    if(request.parmWorkerId() == "")
    {
        errorsList.addEnd("Worker Id must specified.");
        errorCode = #BadRequest;
    }
    else if(worker.RecId == 0)
    {
        errorsList.addEnd(strFmt("Worker not found against worker Id  '%1'.", request.parmWorkerId()));
        errorCode = #NotFound;
    }

    if(request.parmEssRequest() == "")
    {
        errorsList.addEnd(strFmt("ESS request Id must be specified"));
        errorCode = #NotFound;
    }
    else if(NVTrvWorkerExpenseRequest::findESSRequest(request.parmEssRequest()).RecId != 0)
    {
        errorsList.addEnd(strFmt("Travel request with Id '%1' already exist.", request.parmEssRequest()));
        errorCode = #BadRequest;
    }

    if(request.parmFromDate() > request.parmToDate())
    {
        errorsList.addEnd(strFmt("Travel from date must be before or equal to To date."));
        errorCode = #BadRequest;
    }    

    NVTrvWorkerLocation fromLocation = NVTrvWorkerLocation::find(request.parmFromLocation());
    if(request.parmFromLocation() == "")
    {
        errorsList.addEnd("From location must specified.");
        errorCode = #BadRequest;
    }
    else if(fromLocation.RecId == 0)
    {
        errorsList.addEnd(strFmt("From location not found against Id  '%1'.", request.parmFromLocation()));
        errorCode = #NotFound;
    }

    NVTrvWorkerLocation toLocation = NVTrvWorkerLocation::find(request.parmToLocation());
    if(request.parmToLocation() == "")
    {
        errorsList.addEnd("To location must specified.");
        errorCode = #BadRequest;
    }
    else if(toLocation.RecId == 0)
    {
        errorsList.addEnd(strFmt("To location not found against Id  '%1'.", request.parmToLocation()));
        errorCode = #NotFound;
    }

    if(errorCode == #SuccessCode)
    {
        NVTrvWorkerExpenseRequest       travelRequest;

        travelRequest.initValue();

        travelRequest.Worker                = worker.RecId;
        travelRequest.FromLocation          = request.parmFromLocation();
        travelRequest.ToLocation            = request.parmToLocation();
        travelRequest.FromDate              = request.parmFromDate();
        travelRequest.ToDate                = request.parmToDate();
        travelRequest.IncludeLastDayHotel   = request.parmIncludeLastDayHotel();
        travelRequest.IsBudgeted            = request.parmIsBudgeted();
        travelRequest.ESSRequestId          = request.parmEssRequest();
        travelRequest.OrderNumber           = request.parmOrderNumber();
        travelRequest.DocumentNumber        = request.parmDocumentNumber();
        travelRequest.DocumentEntryDate     = request.parmDocumentEntryDate();
        travelRequest.Comment               = request.parmComment();
        travelRequest.ManagerComment        = request.parmManagerComment();
        travelRequest.RequestCreatedDate    = request.parmRequestCreatedDate();

        travelRequest.modifiedField(fieldNum(NVTrvWorkerExpenseRequest, ToLocation));
        travelRequest.insert();
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(retList);

    return responseContract;
}

public NVAPIResponseContract updateTimesheet(NVTimesheetContract request)
{
    int     errorCode  = #SuccessCode;
    List    errorsList = new List(Types::String);
    List    retList    = new List(Types::String);

    PayrollPayCycle payCycle = PayrollPayCycle::findByPayCycle(request.parmPayCycle());

    if (payCycle.RecId == 0)
    {
        errorsList.addEnd(strFmt("Payroll cycle not found against pay cycle '%1'.", request.parmPayCycle()));
        errorCode = #NotFound;
    }

    PayrollPayPeriod payPeriod;

    if (errorCode == #SuccessCode)
    {
        payPeriod = PayrollPayPeriod::findByPayCycleAndDateRange(
        payCycle.RecId,
        request.parmPayPeriodStartDate());

        if (payPeriod.RecId == 0)
        {
            errorsList.addEnd(strFmt(
            "Payroll period not found for pay cycle '%1' and start date %2.",
            request.parmPayCycle(),
            request.parmPayPeriodStartDate()));

            errorCode = #NotFound;
        }
    }

    if (errorCode == #SuccessCode)
    {
        List            lines     = request.parmLines();
        ListIterator    linesIter = new ListIterator(lines);

        while (linesIter.more())
        {
            NVTimesheetLineContract lineContract = linesIter.value();

            NVTimeSheetHeader timesheetHeaderCheck;
            NVTimeSheetLines  timesheetLineCheck;

            select firstonly crosscompany timesheetLineCheck
            join timesheetHeaderCheck
                where timesheetHeaderCheck.RecId        == timesheetLineCheck.TimeSheetHeader
                   && timesheetHeaderCheck.DataAreaId   == timesheetLineCheck.DataAreaId
                   && timesheetHeaderCheck.PayCycleId   == payCycle.PayCycleId
                   && timesheetHeaderCheck.PayPeriod    == payPeriod.RecId
                   && timesheetLineCheck.EmpId          == lineContract.parmWorkerId();

            if (timesheetLineCheck.RecId == 0)
            {
                errorsList.addEnd(strFmt(
                    "Timesheet line not found for pay cycle '%1', period %2 to %3 and worker %4.",
                    request.parmPayCycle(),
                    request.parmPayPeriodStartDate(),
                    request.parmPayPeriodEndDate(),
                    lineContract.parmWorkerId()));

                errorCode = #NotFound;
            }

            linesIter.next();
        }
    }

    if (errorCode == #SuccessCode)
    {
        List            lines     = request.parmLines();
        ListIterator    linesIter = new ListIterator(lines);

        while (linesIter.more())
        {
            NVTimesheetLineContract lineContract = linesIter.value();

            NVTimeSheetHeader timesheetHeaderFound;
            NVTimeSheetLines  timesheetLineFound;

            select firstonly crosscompany timesheetLineFound
                join timesheetHeaderFound
                    where timesheetHeaderFound.RecId        == timesheetLineFound.TimeSheetHeader
                       && timesheetHeaderFound.DataAreaId   == timesheetLineFound.DataAreaId
                       && timesheetHeaderFound.PayCycleId   == payCycle.PayCycleId
                       && timesheetHeaderFound.PayPeriod    == payPeriod.RecId
                       && timesheetLineFound.EmpId          == lineContract.parmWorkerId();

            changecompany(timesheetLineFound.DataAreaId)
            {
                NVTimeSheetLines timesheetLineUpdate;

                ttsbegin;

                select firstonly forupdate timesheetLineUpdate
                where timesheetLineUpdate.RecId == timesheetLineFound.RecId;

                if (timesheetLineUpdate.RecId == 0)
                {
                    ttsabort;

                    errorsList.addEnd(strFmt(
                        "Timesheet line could not be selected for update for worker %1.",
                        lineContract.parmWorkerId()));

                    errorCode = #NotFound;
                    break;
                }

                timesheetLineUpdate.OvertimeHours = lineContract.parmOvertimeHours();
                timesheetLineUpdate.NightHours    = lineContract.parmNightHours();

                List dailyEntryList = lineContract.parmDailyEntries();

                if (dailyEntryList)
                {
                    ListIterator dailyEntryIter = new ListIterator(dailyEntryList);

                    while (dailyEntryIter.more())
                    {
                        NVTimesheetWorkerDailyEntryContract dailyEntryContract = dailyEntryIter.value();

                        timesheetLineUpdate.setValueToDayColumn(
                        dailyEntryContract.parmTransDate(),
                        dailyEntryContract.parmValue());

                        dailyEntryIter.next();
                    }
                }

                timesheetLineUpdate.Status = lineContract.parmStatus();
                timesheetLineUpdate.update();

                ttscommit;
            }

            if (errorCode != #SuccessCode)
            {
                break;
            }

            linesIter.next();
        }
    }

    NVAPIResponseContract responseContract = new NVAPIResponseContract();
    responseContract.parmStatusCode(errorCode);
    responseContract.parmErrorDetails(errorsList);
    responseContract.parmBody(retList);

    return responseContract;
}
